// 항목 배열에서 이름(n)만 뽑는다. null/undefined 항목은 건너뛰고,
// a가 1인 항목의 이름은 대문자로 바꾼다.
function proc(items) {
  return items
    .filter((item) => item != null)
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

// 쉼표로 구분된 문자열을 앞뒤 공백을 제거한 값 배열로 나눈다. 빈 값은 버린다.
function f2(text) {
  return text
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part !== '');
}

module.exports = { proc, f2 };

